})
export class AppComponent {
  heading = 'הקבצים הנדרשים';
  helpText = 'גרור ושחרר קובץ או בחר ממערכת הקבצים';
  description = 'PDF, JPEG or PNG Less than 5MB';
  acceptedFormats = 'image/png, image/jpeg, application/pdf, video/mp4';
  maxFileSize = 5;
  multiple = false;
  isSubmitShown = false;
  status = 'default';
files: AddedFile[] = [];
handleAddFile (e: CustomEvent<{fileDetails: AddedFile}>) {
    console.log('File added:', e.detail);
    this.files = [...this.files, e.detail.fileDetails];
  };
const handleRemoveFile (e: CustomEvent<{fileDetails: AddedFile}>) {
    console.log('File removed:', e.detail);
    const removedFile = e.detail.fileDetails;
    this.files = this.files.filter((uploadedFiles) => uploadedFiles.id !== removedFile.id));
  };
}

